WITH a AS (
    SELECT a.assay_id, a.molregno, a.type, a.pchembl_value FROM activities a WHERE a.type = 'IC50' AND a.pchembl_value IS NOT NULL
), t AS (
    SELECT ass.assay_id, ass.chembl_id AS assay_chembl_id, ass.tid FROM assays ass WHERE ass.assay_organism = 'Homo sapiens'
), td AS (
    SELECT td.tid, td.target_type, td.tax_id, td.chembl_id AS target_chembl_id FROM target_dictionary td WHERE td.chembl_id = 'CHEMBL233'
), cs AS (
    SELECT cs.molregno, cs.canonical_smiles FROM compound_structures cs
), d AS (
    SELECT a.assay_id, t.assay_chembl_id, td.target_type, td.tax_id, cs.canonical_smiles, dmd.pref_name AS molecule_chembl_id, a.type AS standard_type, a.pchembl_value
    FROM a
    JOIN t ON a.assay_id = t.assay_id
    JOIN td ON t.tid = td.tid AND td.chembl_id = 'CHEMBL233'
    JOIN compound_structures dmd ON a.molregno = dmd.molregno
    JOIN compound_structures cs ON a.molregno = cs.molregno
    WHERE t.assay_id IS NOT NULL AND td.tid IS NOT NULL
)
SELECT DISTINCT assay_chembl_id, target_type, tax_id, canonical_smiles, molecule_chembl_id, standard_type, pchembl_value FROM d ORDER BY molecule_chembl_id ASC, assay_chembl_id ASC LIMIT 1000;
